package com.stockpass.config;
import com.stockpass.model.User; import com.stockpass.repository.UserRepository; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.Bean; import org.springframework.context.annotation.Configuration; import org.springframework.security.crypto.password.PasswordEncoder;
@Configuration public class DataInitializer { @Bean CommandLineRunner seed(UserRepository repo,PasswordEncoder encoder){return args->{if(!repo.existsByEmailIgnoreCase("admin@stockpass.com")){User u=new User();u.setName("Administrador");u.setEmail("admin@stockpass.com");u.setPassword(encoder.encode("123456"));u.setRole("ADMIN");repo.save(u);} if(!repo.existsByEmailIgnoreCase("gestor@stockpass.com")){User u=new User();u.setName("Gestor");u.setEmail("gestor@stockpass.com");u.setPassword(encoder.encode("123456"));u.setRole("GESTOR");repo.save(u);}};}}
